import { integer, sqliteTable, text } from 'drizzle-orm/sqlite-core';
import type {
  ReferenceDiscovery,
  ReferenceImportPlan,
} from '../../types/reference-onboarding';

export const referenceDiscoveries = sqliteTable('reference_discoveries', {
  id: text().primaryKey(),
  body: text({ mode: 'json' }).$type<ReferenceDiscovery>().notNull(),
});
export const referencePlans = sqliteTable('reference_plans', {
  id: text().primaryKey(),
  body: text({ mode: 'json' }).$type<ReferenceImportPlan>().notNull(),
});
export const plannedSources = sqliteTable('planned_sources', {
  sourceId: text('source_id').primaryKey(),
  discoveryId: text('discovery_id').notNull(),
  collectionId: text('collection_id').notNull(),
  collectionIds: text('collection_ids', { mode: 'json' })
    .$type<string[]>()
    .notNull()
    .default([]),
});
export const referenceOnboarding = sqliteTable('reference_onboarding', {
  singleton: integer().primaryKey(),
  state: text({
    enum: ['pending', 'later', 'dismissed', 'complete'],
  }).notNull(),
  offeredAt: text('offered_at'),
  remindAt: text('remind_at'),
});

export const connectorOnboarding = sqliteTable('connector_onboarding', {
  provider: text({ enum: ['cosmos', 'pinterest', 'arena', 'x'] }).primaryKey(),
  state: text({
    enum: ['pending', 'later', 'dismissed', 'complete'],
  }).notNull(),
  offeredAt: text('offered_at'),
  remindAt: text('remind_at'),
});
